import { readFileSync, writeFileSync, readdirSync, unlinkSync } from "fs";
import { join } from "path";

const root = process.cwd();
const srcDir = join(root, "src");
const manifestPath = join(srcDir, "command-manifest.json");
const packageJsonPath = join(root, "package.json");
const presetsGenPath = join(srcDir, "presets.gen.ts");
const generatedEntryHeader =
  "// Automatically generated by scripts/sync-commands.mjs. Do not edit manually.";

function readManifest() {
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
  if (!Array.isArray(manifest)) {
    throw new Error("command-manifest.json must export an array.");
  }
  return manifest;
}

function validatePreference(preference, commandName) {
  if (
    !preference ||
    typeof preference.name !== "string" ||
    typeof preference.type !== "string" ||
    typeof preference.title !== "string"
  ) {
    throw new Error(
      `Invalid preference in ${commandName}. Each preference requires name, type, and title.`,
    );
  }
}

function validateCommand(command) {
  if (
    !command ||
    typeof command.name !== "string" ||
    typeof command.title !== "string" ||
    typeof command.description !== "string" ||
    typeof command.icon !== "string"
  ) {
    throw new Error(
      "Each command in command-manifest.json requires name, title, description, and icon.",
    );
  }

  if (command.mode !== "view" && command.mode !== "no-view") {
    throw new Error(
      `Invalid mode for ${command.name}. Expected "view" or "no-view".`,
    );
  }

  if (command.mode === "no-view" && typeof command.prompt !== "string") {
    throw new Error(
      `Text command ${command.name} requires a prompt in command-manifest.json.`,
    );
  }

  if (
    command.preferences !== undefined &&
    !Array.isArray(command.preferences)
  ) {
    throw new Error(
      `Command ${command.name} has invalid preferences. Expected an array.`,
    );
  }

  for (const preference of command.preferences || []) {
    validatePreference(preference, command.name);
  }
}

function buildCommandDefinition(command) {
  const definition = {
    name: command.name,
    title: command.title,
    description: command.description,
    mode: command.mode,
    icon: command.icon,
  };

  if (command.mode === "no-view") {
    const commandPreferences = [];
    commandPreferences.push({
      name: "customPrompt",
      type: "textfield",
      required: false,
      title: "Custom Prompt",
      description:
        command.promptDescription ||
        "Customize the prompt for this command. Use {Default Language} and {Expression Language} as placeholders.",
      default: command.prompt,
    });

    if (Array.isArray(command.preferences)) {
      commandPreferences.push(...command.preferences);
    }

    definition.preferences = commandPreferences;
  }

  return definition;
}

function buildPresetEntryContent(commandName) {
  return `${generatedEntryHeader}
import { getTextCommandConfig } from "./commandManifest";
import { runTextCommand } from "./core/command";

export const commandConfig = getTextCommandConfig("${commandName}");

export default async function command(): Promise<void> {
  return runTextCommand(commandConfig);
}
`;
}

function buildPresetsContent(presetNames) {
  const presets = presetNames
    .map((commandName) => `  getTextCommandConfig("${commandName}"),`)
    .join("\n");

  return `${generatedEntryHeader}
import { getTextCommandConfig } from "./commandManifest";

export const PRESETS = [
${presets}
];
`;
}

const manifest = readManifest();
const commands = [];
const presetNames = [];

for (const command of manifest) {
  validateCommand(command);
  commands.push(buildCommandDefinition(command));

  if (command.mode === "no-view") {
    presetNames.push(command.name);
    writeFileSync(
      join(srcDir, `${command.name}.ts`),
      buildPresetEntryContent(command.name),
    );
  }
}

for (const fileName of readdirSync(srcDir)) {
  if (!fileName.startsWith("ai-") || !fileName.endsWith(".ts")) continue;
  const filePath = join(srcDir, fileName);
  const contents = readFileSync(filePath, "utf8");
  const commandName = fileName.replace(/\.ts$/, "");
  if (
    contents.startsWith(generatedEntryHeader) &&
    !presetNames.includes(commandName)
  ) {
    unlinkSync(filePath);
  }
}

const packageJson = JSON.parse(readFileSync(packageJsonPath, "utf8"));
packageJson.commands = commands;
writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2) + "\n");

writeFileSync(presetsGenPath, buildPresetsContent(presetNames));

console.log(
  `Synced ${commands.length} commands and generated presets manifest.`,
);
